//! CPU parity of build_mrope_positions against HF get_rope_index.
//! Fixture is generated by benchmarks/vision/dump_mrope_reference.py and
//! committed, so this test needs no torch.

use hipfire_arch_qwen35_vl::mrope::{build_mrope_positions, mrope_axis_for_freq, ImageSpan};
use serde_json::Value;

fn fixture() -> Value {
    let raw = include_str!("fixtures/mrope_reference.json");
    serde_json::from_str(raw).expect("fixture parses")
}

/// Rebuild the span list + token count from a fixture case's segments.
fn spans_for(case: &Value) -> (usize, Vec<ImageSpan>) {
    let merge = case["merge"].as_u64().unwrap() as usize;
    let mut spans = Vec::new();
    let mut n = 0usize;
    for seg in case["segments"].as_array().unwrap() {
        let kind = seg[0].as_str().unwrap();
        if kind == "text" {
            n += seg[1].as_u64().unwrap() as usize;
        } else {
            let gh = seg[1].as_u64().unwrap() as usize;
            let gw = seg[2].as_u64().unwrap() as usize;
            let len = (gh / merge) * (gw / merge);
            spans.push(ImageSpan { start: n, len, grid_h: gh, grid_w: gw });
            n += len;
        }
    }
    (n, spans)
}

fn check_case(name: &str) {
    let fx = fixture();
    let case = &fx[name];
    let merge = case["merge"].as_u64().unwrap() as usize;
    let (n, spans) = spans_for(case);
    assert_eq!(n, case["n_tokens"].as_u64().unwrap() as usize, "{name}: token count");

    let got = build_mrope_positions(n, &spans, merge);
    let want = case["positions"].as_array().unwrap();
    assert_eq!(got.positions.len(), want.len(), "{name}: positions length");

    for (i, w) in want.iter().enumerate() {
        let expect = [
            w[0].as_i64().unwrap() as i32,
            w[1].as_i64().unwrap() as i32,
            w[2].as_i64().unwrap() as i32,
        ];
        assert_eq!(
            got.positions[i], expect,
            "{name}: token {i} position mismatch (got {:?}, want {:?})",
            got.positions[i], expect
        );
    }
    assert_eq!(
        got.rope_delta,
        case["rope_delta"].as_i64().unwrap() as i32,
        "{name}: rope_delta"
    );
}

#[test]
fn parity_smoke_70x54() { check_case("smoke_70x54"); }

#[test]
fn parity_wide_28x70() { check_case("wide_28x70"); }

#[test]
fn parity_text_img_text() { check_case("text_img_text"); }

/// A pure-text sequence MUST equal plain sequential on all three axes. This
/// is the regression guard for the untouched text-only path: if it ever
/// diverges, text generation breaks.
#[test]
fn text_only_equals_sequential() {
    check_case("text_only");
    let got = build_mrope_positions(40, &[], 2);
    for i in 0..40 {
        assert_eq!(got.positions[i], [i as i32; 3], "text token {i}");
    }
    assert_eq!(got.rope_delta, 0, "pure text must have zero delta");
}

/// The image advance is ONE GRID DIMENSION, not the token count. A 70x54
/// grid contributes 945 tokens but advances the cursor by only 35. This test
/// exists because advancing by token count is the natural mistake and
/// reproduces the exact bug being fixed.
#[test]
fn image_advance_is_grid_dimension_not_token_count() {
    let spans = [ImageSpan { start: 0, len: 945, grid_h: 70, grid_w: 54 }];
    let got = build_mrope_positions(946, &spans, 2);
    // Token 945 is the first text token after the image.
    assert_eq!(
        got.positions[945],
        [35, 35, 35],
        "text after a 70x54 image must resume at 35 (max(70,54)/2), not 945"
    );
}

/// Interleaved band mapping [THWTHW...TT], NOT chunked [TTT...HHH...WWW].
#[test]
fn band_mapping_is_interleaved() {
    let sec = [11usize, 11, 10];
    let axes: Vec<usize> = (0..32).map(|d| mrope_axis_for_freq(d, sec)).collect();
    assert_eq!(&axes[0..6], &[0, 1, 2, 0, 1, 2], "leading THWTHW pattern");
    assert_eq!(axes[30], 0, "d=30 -> T");
    assert_eq!(axes[31], 1, "d=31 -> H (31 < 3*11)");
    assert_eq!(axes.iter().filter(|&&a| a == 0).count(), 11, "T count");
    assert_eq!(axes.iter().filter(|&&a| a == 1).count(), 11, "H count");
    assert_eq!(axes.iter().filter(|&&a| a == 2).count(), 10, "W count");
}
